-- it_frameworks
insert into public.it_frameworks (
  id, status, name, slug, short_description, problem_statement, outcome_statement,
  target_audience, when_to_use, when_not_to_use, method_summary, journey_stage_id,
  priority_score, priority_rationale, source_strength, source_note, flagship,
  display_order, seo_title, seo_description, published_at
) values (
  'bd063cd6-3bdc-e7a0-47fa-dabc2cd8a448', 'published', 'Product Idea Assessor', 'product-idea-assessor', 'Work out how much evidence your idea actually needs before you commit real time or money to it.', 'Founders routinely over-invest in ideas that needed more validation, and under-invest in ideas that needed less — because nothing tells them how much scepticism a given idea actually deserves before they start.', 'A Copy/Improve/Differentiate classification, a scored read on how strong your evidence is, and a clear next action.',
  'Solo founders and early-stage teams deciding how cautiously to approach a specific idea.', 'Use as soon as you can state the idea in a sentence, before you''ve written a business plan or built anything.', 'Not a substitute for actually talking to customers — it tells you how much evidence you need, not whether you already have it.', 'Classify the idea as Copy (a working model applied to a new context), Improve (a specific improvement on an existing, working approach) or Differentiate (asking people to adopt a genuinely new behaviour). Each category carries a different risk profile and needs a different amount of evidence before you commit. Answer four evidence questions — problem evidence, behaviour evidence, differentiation clarity and target specificity — and the assessor combines your classification with those answers into a readiness verdict and a concrete next step.', '503582d1-29fb-9e68-af12-1375bd33ab3a',
  96, 'Ranked #1 in the source-material opportunity portfolio (spec v3 §37): broad audience fit, strong existing source material, and it establishes the reusable Guide/Template/Tool pattern every later family follows.', 'strong', 'Developed from A Bit Gamey material on testing product ideas before building, including the Copy–Improve–Differentiate classification.', true,
  1, 'Product Idea Assessor — is this idea worth pursuing?', 'Classify your idea as Copy, Improve or Differentiate and get a scored, evidence-based read on whether it''s ready to proceed.', '2026-08-01T09:00:00Z'
)
on conflict (id) do update set status = excluded.status, name = excluded.name, slug = excluded.slug,
