insert into public.it_frameworks (
  id, status, name, slug, short_description, problem_statement, outcome_statement,
  target_audience, when_to_use, when_not_to_use, method_summary, journey_stage_id,
  priority_score, priority_rationale, source_strength, source_note, flagship,
  display_order, seo_title, seo_description, published_at
) values (
  '4d32e24c-2646-908d-569c-a9789dfb06e1', 'published', 'Better Decision Maker', 'better-decision-maker', 'Given the evidence you have, work out what you should actually do.', 'Founders wait for certainty that never arrives, or decide on instinct without noticing that some decisions are cheap to reverse and others aren''t — so easy, reversible calls get over-analysed while genuinely risky, one-way ones get rushed.', 'A documented decision, reasoned through rather than made on instinct alone.',
  'Founders facing an important decision under uncertainty.', 'Use once you have real options to weigh — after the evidence-gathering stages, not instead of them.', 'Not useful for decisions that are genuinely reversible and low-stakes — the process itself costs more time than a quick two-way-door decision deserves.', 'Classify the decision by reversibility first: a two-way door is cheap to back out of and deserves a fast call; a one-way door is expensive or impossible to reverse and deserves real analysis. Invert the question — instead of ''what would make this succeed,'' ask ''what would guarantee it fails'' — to turn an abstract comparison into a concrete checklist of what to avoid. Check the decision against any simple rules you''ve already committed to, so routine decisions don''t need fresh analysis every time. For decisions with real options to compare, estimate expected value for each — likelihood of success, impact if it works, and effort to attempt — and when two options come out close, let reversibility break the tie rather than agonising further.', '3f7a87a9-2a65-573c-b0ed-c66ad4f7d9f0',
  94, 'Ranked #3 in the source-material opportunity portfolio (spec v3 §37): the natural next step once Product Idea Assessor and Customer Discovery Kit have produced evidence — this family is where that evidence actually turns into a decision.', 'strong', 'Developed from A Bit Gamey material on decision-making under uncertainty, including reversibility (''two-way door'' vs ''one-way door''), inversion, simple rules and expected-value estimation.', true,
  3, 'Better Decision Maker — decide under uncertainty without waiting for certainty', 'Four techniques for making an important founder decision: reversibility, inversion, simple rules and expected value — with a worksheet and a comparison tool.', '2026-08-09T09:00:00Z'
)
