-- it_products
insert into public.it_products (
  id, product_type, access_type, status, name, slug, short_description, full_description,
  outcome_statement, target_audience, when_to_use, when_not_to_use,
  completion_minutes_min, completion_minutes_max, skill_level, current_version,
  price_minor, compare_at_price_minor, currency_code, licence_id, featured,
  published_at, scheduled_for, seo_title, seo_description, schema_data,
  framework_id, tool_key
) values (
  '4a4bf14a-af34-dfa8-dca5-9c49cda6e795', 'template', 'free', 'published', 'Product Idea Snapshot', 'product-idea-snapshot', 'A one-page worksheet that turns a vague idea into a testable statement of who it''s for, what problem it solves, and why now.', 'Most ideas don''t fail because they''re bad — they fail because they''re vague. The Product Idea Snapshot forces you to state the problem, the customer, the proposed solution and your riskiest assumption on a single page, in plain language. It''s the fastest way to find out whether an idea is specific enough to test, and it''s the template every other Incy Templates worksheet assumes you''ve already completed.',
  'Leave with a single-page snapshot you can show a co-founder, mentor or customer in under two minutes.', 'Solo founders and early-stage teams who have an idea but haven''t written it down in a form anyone else could evaluate.', 'Use this in the first hour of taking an idea seriously, before you''ve spent time building or researching.', 'Not for ideas you''ve already validated with real customers — move on to the Copy–Improve–Differentiate Assessment instead.',
  15, 25, 'beginner', '1.0',
  null, null, 'GBP', '488fbee7-849e-4e17-2d2e-e386ec5328ca', true,
  '2026-06-02T09:00:00Z', null, 'Product Idea Snapshot — free one-page template', 'A free one-page worksheet that turns a vague idea into a testable statement of the customer, problem and riskiest assumption.', '{"placeholder":true}'::jsonb,
  null, null
)
