  framework_id, tool_key
) values (
  'af2edcc3-4630-bbd6-e144-29ff50d794b1', 'template', 'free', 'published', 'Copy–Improve–Differentiate Assessment', 'proven-better-new-assessment', 'Classify your idea as Copy, Improve or Differentiate so you know how much evidence you actually need before committing.', 'The Copy–Improve–Differentiate method (see the Product Idea Assessor guide) separates ideas that copy a working model, ideas that improve on an existing one, and ideas that introduce genuinely new behaviour. Each category carries a different risk profile and needs a different amount of validation before you commit real time or money. This worksheet walks you through the classification and hands you the evidence checklist that follows from your answer.',
  'A clear verdict — Copy, Improve or Differentiate — plus the specific evidence that verdict requires before you proceed.', 'Founders and product people deciding how cautiously to approach an idea.', 'Use immediately after the Product Idea Snapshot, before writing a business plan or building anything.', 'Not a substitute for actual customer interviews — it tells you how much evidence you need, not whether you have it yet.',
  20, 30, 'beginner', '1.1',
  null, null, 'GBP', '488fbee7-849e-4e17-2d2e-e386ec5328ca', true,
  '2026-06-02T09:00:00Z', null, 'Copy–Improve–Differentiate Assessment — free idea evaluation template', 'Classify an idea as Copy, Improve or Differentiate and get the evidence checklist that follows, free.', '{"placeholder":true}'::jsonb,
  'bd063cd6-3bdc-e7a0-47fa-dabc2cd8a448', null
)
