  '8adc006c-06fb-911d-340c-3ec0fadf6724', 'tool', 'free', 'published', 'Expected Value Comparator', 'better-decision-maker-tool', 'Compare two options by expected value and get a reversibility-aware recommendation.', 'Answer four questions about each of two options — likelihood of success, impact if it works, effort to attempt, and whether it''s a one-way or two-way door — and get an expected-value score for each, a recommendation, a confidence read on how clear the gap is, and one next step. Usable anonymously, with no account required.',
  'An expected-value comparison of two options, a recommendation, and one clear next step.', 'Founders comparing two real options and wanting a structured, deterministic read on which one to take.', 'Use once you''ve narrowed a decision down to two real options worth comparing.', 'Not useful for more than two options at once, or for decisions that don''t have distinct alternatives to compare.',
  5, 10, 'beginner', '1.0',
  null, null, 'GBP', null, true,
  '2026-08-09T09:00:00Z', null, 'Expected Value Comparator — free decision-comparison tool', 'Compare two options by expected value and get a reversibility-aware recommendation, free, no account required.', '{"placeholder":true}'::jsonb,
  '4d32e24c-2646-908d-569c-a9789dfb06e1', 'better-decision-maker'
)
